// Copies the App pack UI sources (packages/engine/app-packs/*.tsx) into
// src/bundles/app-pack-sources.generated.ts so the engine can ship them as
// strings. Run after editing any app pack:  pnpm --filter @yumina/engine gen:app-packs
// `--check` exits non-zero when the generated file is stale (used by the test).
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const srcDir = join(root, "app-packs");
const outFile = join(root, "src", "bundles", "app-pack-sources.generated.ts");

const ids = readdirSync(srcDir).filter((f) => f.endsWith(".tsx")).map((f) => f.slice(0, -4)).sort();
const lines = [
  "// GENERATED by scripts/gen-app-packs.mjs from packages/engine/app-packs/*.tsx — do not edit.",
  "export const APP_PACK_SOURCES: Record<string, string> = {",
  ...ids.map((id) => {
    // Normalize line endings so Windows checkouts produce the same bytes.
    const code = readFileSync(join(srcDir, id + ".tsx"), "utf8").replace(/\r\n?/g, "\n");
    return "  " + JSON.stringify(id) + ": " + JSON.stringify(code) + ",";
  }),
  "};",
  "",
];
const next = lines.join("\n");

if (process.argv.includes("--check")) {
  let current = "";
  // A Windows checkout may have turned the file's LF into CRLF.
  try { current = readFileSync(outFile, "utf8").replace(/\r\n?/g, "\n"); } catch {}
  if (current !== next) {
    console.error("app-pack-sources.generated.ts is stale — run: pnpm --filter @yumina/engine gen:app-packs");
    process.exit(1);
  }
} else {
  writeFileSync(outFile, next);
  console.log("wrote " + ids.length + " app packs: " + ids.join(", "));
}
